def take_slices(available, wanted):
    if wanted > available:
        raise ValueError(f"Only {available} slices left")
    return available - wanted

try:
    left = take_slices(3, 5)
except ValueError as error:
    print("Order refused:", error)

class Order:
    def __init__(self, customer):
        self.customer = customer
        self.items = []

    def add(self, item, price):
        self.items.append((item, price))

    def total(self):
        return sum(price for _, price in self.items)

order = Order("Ana")
order.add("margherita", 8.5)
order.add("cola", 1.5)
print(order.customer, len(order.items), order.total())

class Pizza:
    def __init__(self, name, price):
        if price <= 0:
            raise ValueError("Price must be positive")
        self.name = name
        self.price = price

    def __str__(self):
        return f"{self.name} (£{self.price:.2f})"

print(Pizza("veggie", 9))

def slices(pizzas):
    return pizzas * 8

if __name__ == "__main__":
    print(slices(int(input())))
